# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Reservation route access through reservation_post" do
  include_context "timekeeping entry writes"

  it "reservation_post matrix refuses every credential on every route, changes nothing after each call, and the owner still commits" do
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    employee = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    free_entry = timekeeping_arrange.entry(company:, user: employee, project:)
    prepared_entry = timekeeping_arrange.entry(company:, user: employee, project:)
    billable = timekeeping_arrange.reserved_entry(company:, invoice_id: 501, state: "committed")
    agent_entry = timekeeping_arrange.entry(company:, user: employee, project:, agent_id: 77)
    owner = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: reservation_routes)
    operation_id = SecureRandom.uuid
    expect(reservation_post("prepare", company:, credential: owner,
                            body: { "invoice_id" => 503, "operation_id" => operation_id, "disposition" => "active",
                                    "entries" => [prepared_entry] }).status).to eq(200)
    snapshot = lambda do
      { entries: Entry.order(:id).pluck(:id, :bill_status, :agent_id, :version),
        reservations: Reservation.order(:entry_id, :invoice_id).pluck(:entry_id, :invoice_id, :state),
        operations: InvoiceOperation.order(:id).pluck(:company_id, :operation_id, :state, :desired_entry_ids),
        counts: reservation_row_counts }
    end
    baseline = snapshot.call
    expect(baseline[:reservations]).to include([prepared_entry, 503, "provisional"], [billable, 501, "committed"])
    expect(baseline[:reservations].map(&:first)).not_to include(free_entry)
    expect(baseline[:operations]).to include([company, operation_id, "prepared", [prepared_entry]])
    expect(baseline[:entries]).to include([billable, "unbilled", nil, Entry.find(billable).version],
                                          [agent_entry, "unbilled", 77, Entry.find(agent_entry).version])

    bodies = {
      "prepare" => [{ "invoice_id" => 502, "operation_id" => SecureRandom.uuid, "disposition" => "active", "entries" => [free_entry] }, {}],
      "commit" => [{ "invoice_id" => 503, "operation_id" => operation_id }, {}],
      "abort" => [{ "invoice_id" => 503, "operation_id" => operation_id }, {}],
      "mark_billed" => [{ "operation_id" => SecureRandom.uuid }, { invoice_id: 501 }],
      "detach_entries" => [{ "operation_id" => SecureRandom.uuid }, { agent_id: 77 }]
    }
    reservation_routes.each do |route|
      body, path_params = bodies.fetch(route)
      credentials = {
        "no token" => [nil, 401, "unauthorized"],
        "user token" => [timekeeping_arrange.token_for(timekeeping_arrange.user(company:, role: "owner")), 403, "forbidden"],
        "no operations" => [timekeeping_arrange.service_identity(company:, name: "reporting", operations: []), 403, "forbidden"],
        "all but this route" => [timekeeping_arrange.service_identity(company:, name: "invoice-boundary",
                                                                      operations: reservation_routes - [route]), 403, "forbidden"],
        "other company" => [timekeeping_arrange.service_identity(company: other_company, name: "invoice-boundary",
                                                                 operations: reservation_routes), 404, "not_found"]
      }
      credentials.each do |label, (credential, status, reason)|
        answer = reservation_post(route, company:, credential:, body:, **path_params)

        expect([route, label, answer.status, answer.parsed_body]).to eq([route, label, status, { "reason" => reason }])
        expect([route, label, snapshot.call]).to eq([route, label, baseline])
      end
    end

    committed = reservation_post("commit", company:, credential: owner, body: { "invoice_id" => 503, "operation_id" => operation_id })
    expect([committed.status, committed.parsed_body]).to eq([200, { "reserved" => 1, "released" => 0 }])
  end
end
